INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Obscurite Magie: The Blood of Kings', 'Adventurer Lietta Fane''s mentor and guardian Negel was murdered. She swears vengeance against his murderer and sets off to confront her destiny. Take off for adventure through the Giselian Empire while uncovering the truth behind Negel''s murder in this timeless turn-based RPG. Face off against a diverse set of enemies and bosses, discover and gain a wide variety of loot, and level up to overpower your foes!' FROM games WHERE igdb_id = 245948 ON CONFLICT (game_id, language_code) DO NOTHING;
