INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Two Moons', 'A Comedy/Walking Simulator RPG that follows a 4th-wall breaking main character who knows he is in a crappy RPG maker game and wants no part of it, but he is forced into being the main character by a series of infinite loop Yes/No choices where No isn''t a real option. Chaos ensues in this wacky game.' FROM games WHERE igdb_id = 249939 ON CONFLICT (game_id, language_code) DO NOTHING;
