INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dora Think Nobita''s Exciting Brain Adventure', 'Doraemon: Nobita''s Exciting Adventure is an adventure puzzle RPG game. In order to rescue Doraemon who was accidentally imprisoned in the mysterious city, you solve graphics, puzzles, mazes and other problems along the way to defeat robot soldiers, and adventure with Nobita, Shizuka, Fat Tiger, and Suneo. The stage of the adventure is the world in the secret prop "Game Book". The interior of the huge castle is divided into 10 floors, and each floor consists of multiple levels. The level screen is in 3D RPG style, and robot soldiers will block Nobita and his friends wherever they go.' FROM games WHERE igdb_id = 233929 ON CONFLICT (game_id, language_code) DO NOTHING;
