INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ira', 'A character-based shooter with roguelike elements, IRA celebrates the artistry of what shooter fans call “bullet hell”: enemy projectiles that weave intricate, geometric patterns across the screen and force you to seek out the precarious safe spaces between them. Set in an Eastern-influenced fantasy world marked by ethereal beauty as well as grave danger, it’s a procedurally generated action game that requires skill, inspires strategy and rewards patience.' FROM games WHERE igdb_id = 166044 ON CONFLICT (game_id, language_code) DO NOTHING;
