INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Roterra 4: Magical Revolution', 'Games presents the newest member of the Roterra family: Roterra 4: Magical Revolution. This new installment of the chart-topping series offers 35 levels of all new hand-built puzzles that intensify the perspective challenging journey through this fairytale world of gravity twists, scrambled paths and rotating blocks. 70+ unique puzzles await the player as they travel through mysterious lava-filled caves, explore icy extremes and devastating deserts, and interact with the world of Roterra in new ways.' FROM games WHERE igdb_id = 234605 ON CONFLICT (game_id, language_code) DO NOTHING;
