INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '24 Solar Terms', '24 Solar Terms is a seek and find puzzle game with the theme of the traditional Chinese twenty-four solar terms. The game connects the climate and farming of various solar terms through farming proverbs, myths and fables. Help local farmers solve problems and experience the story of 24 solar terms.' FROM games WHERE igdb_id = 158663 ON CONFLICT (game_id, language_code) DO NOTHING;
