INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Queen of Moths', 'It''s a winter night. You are coming home by train. You have to change trains at a small train station in the middle of the forest.It''s not the first time you''ve traveled this route. But now you feel like something is different. As if something was watching you.' FROM games WHERE igdb_id = 253515 ON CONFLICT (game_id, language_code) DO NOTHING;
