INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beautiful Sakura: Surfing Club', 'A visual novel focused on mental health and personal identity. Help your character fit into the new city you moved to and find new friends. As part of your journey, you will be able to listen to the people around you and learn to surf for the first time. Player choice affects how the narrative will progress, including special dialogue to discover for key scenes.' FROM games WHERE igdb_id = 265240 ON CONFLICT (game_id, language_code) DO NOTHING;
