INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neon Marble Rust', 'Play as one of 3 Houses: Neon, Marble, or Rust! Each faction is completely unique: buildings, units, even resources are unique to each House. A two-state rollback system ensures smooth online gameplay, while a mix of challenging mechanics and automation allow you to play (and win) how you want!' FROM games WHERE igdb_id = 267019 ON CONFLICT (game_id, language_code) DO NOTHING;
