INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hoop Land', 'Get ready for tip off at center court in the latest hoops title by Koality Game! Choose a league, select a team and lead your players to the Championship. Dribble the ball up court and cross-over your opponent for the step back three. Swish! Or run a fast break offense and throw the lob to your teammate for the alley-oop. Slam dunk! Either way, you can become the next dynasty in the hottest basketball simulation game on the market. Welcome to Hoop Land.' FROM games WHERE igdb_id = 250996 ON CONFLICT (game_id, language_code) DO NOTHING;
