INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Broken Spectre', 'Broken Spectre is a cosmic horror narrative adventure game developed in collaboration with the makers of The Blair Witch Project. A cryptic message left by her father takes Casey back to the abandoned trails of Coldblood Mountain, a remote wilderness that has haunted her family for generations. In addition to its unique, macabre visual style, Broken Spectre takes advantage of the Meta Quest 2’s immersive hand-tracking controls to bring unparalleled realism to the game’s gruesome body horror elements.' FROM games WHERE igdb_id = 242871 ON CONFLICT (game_id, language_code) DO NOTHING;
