INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Imae: Guardian Girl', 'Imae Girl is a fast-paced 2D action RPG featuring vibrant pixel art and hack-and-slash combat. Players take on the role of Imae, a brave warrior tasked with defeating waves of monsters and formidable bosses across diverse environments. The game emphasizes character growth through a deep progression system, allowing players to collect powerful gear, unlock unique skills, and customize their playstyle. Combining retro aesthetics with modern action mechanics, Imae Girl offers a challenging experience centered on strategic combat and continuous hero development.' FROM games WHERE igdb_id = 387536 ON CONFLICT (game_id, language_code) DO NOTHING;
