INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Growth', 'Growth is a cozy, hex grid based soft-strategy game. Explore and populate a procedurally generated world by utilizing the unique abilities of animals. Growth blends the beauty of cozy exploration with challenging navigation around obstacles such as mountains and rivers to populate fertile soil, transforming barren landscapes into lush forests, meadows, and more. Experience an unforgettable mix of discovery and strategy. Start growing your own idyllic landscape!
