INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teravit', 'Teravit is an open-world sandbox RPG where you can run, fly, dig, build, and explore the voxel world in your own unique way. Adventurers explore a vast, randomly generated world with a variety of biomes and cities with different characteristics, crafting equipment and items to take on strongholds of vicious monsters to save the world from the clutches of evil. Set forth on an adventure and create your own lasting story. Explore the map in earnest, collecting items, excavating terrain with explosives, and even creating block art. The ultimate goal in this open-world is yours to decide.' FROM games WHERE igdb_id = 167863 ON CONFLICT (game_id, language_code) DO NOTHING;
