INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cave Ranger', 'When the Bitty Gang steals the town''s livelihood and takes it underground, a lone, brave cowboy must come to the rescue. Cave Ranger is an 8-bit inspired, retro platform game. Rescue sheep, fight outlaws, and face down dangerous critters. With a whip and pistol at his disposal, the cave ranger must traverse old mines, water reservoirs, and even a saw mill! It is a lighthearted, laid back western, full of platformer fun.' FROM games WHERE igdb_id = 239619 ON CONFLICT (game_id, language_code) DO NOTHING;
