INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ruinarch', 'Ruinarch is a simulation sandbox game where you create obstacles and cause conflicts in procedurally generated fantasy worlds. Inspired by story generator games like Rimworld and Dwarf Fortress, weaving tales of both anguish and humor is central to Ruinarch’s gameplay. The game gives you all the infernal tools you''ll need to toy with people''s lives and relationships.' FROM games WHERE igdb_id = 138411 ON CONFLICT (game_id, language_code) DO NOTHING;
