INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Friendzone', 'Friendzone is a visual novel-dating sim that began as a small hobby project for my friends, but evolved into a full-fledged dating sim. Featuring 12 romantic routes, 10-12 hours of original content (that''s over 17,500 blocks of dialogue), and a plethora of minigames, Friendzone (using a wacky cast and zany situations) captures the cute, heartwarming, and sometimes awkward aspects of romance in high school. Whoops, that''s the school bell. We''ll see you in homeroom!' FROM games WHERE igdb_id = 284427 ON CONFLICT (game_id, language_code) DO NOTHING;
