INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hop n Pee Dreams VR', 'Hop n Pee Dreams VR is a spirited platformer bursting with innovative VR mechanics. Embark on a short dream through cylindrical platforms as you hoard beers, dodge barrels, and search for relief amidst rock, funk and the sublime Clair de Lune! Strap in for a pee-rific adventure!' FROM games WHERE igdb_id = 259094 ON CONFLICT (game_id, language_code) DO NOTHING;
