INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Celebrating Lake Xochimilco', 'May 20th 2023’s interactive Google Doodle celebrates Lake Xochimilco, a natural lake near Mexico City that is the last remaining native habitat for axolotls in the world (cousins of the salamander). The lake was once home to the ancient Aztec civilization during the 15th century, and eventually landowners in the colonial period took over occupation of the lake. On this day in 1920, the Mexican government returned Lake Xochimilco back to the locals. Lake Xochimilco now serves as a recreational site, cultural attraction, and home to the rare axolotl species.' FROM games WHERE igdb_id = 250299 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 250299 AND c.slug = 'google' ON CONFLICT DO NOTHING;
