INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('surprise-cat', 213593, '2023-05-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co539p.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1sra.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Surprise Cat', 'Surprise Cat is a hidden object game with puzzles. Unleash your inner feline with original gravity-defying gameplay and mind-bending puzzles. Search for hidden objects and use them to defeat your enemies!' FROM games WHERE igdb_id = 213593 ON CONFLICT (game_id, language_code) DO NOTHING;